// ===== IMPOSTAZIONI — modifica solo i valori a destra =====
return [
  {
    json: {
      // ID del Google Sheet "NOVA - Database" (la parte dell'URL tra /d/ e /edit)
      id_foglio: 'INCOLLA_QUI_ID_GOOGLE_SHEET',
      // ID del workflow "00 - NOVA - Gmail (caselle)" (lo trovi nell'URL del workflow)
      id_workflow_gmail: 'INCOLLA_QUI_ID_WORKFLOW_00',

      // MODALITÀ TEST: true = tutte le mail vanno a email_test (non ai lead) e il lead viene segnato "TEST".
      // Metti false solo quando REGOLE e TESTI sono pronti e il warm-up è finito.
      modalita_test: true,
      email_test: 'tua.email@esempio.it',

      // Chi firma le mail (se nella scheda CASELLE c'è nome_mittente, vince quello)
      nome_mittente: 'Mario Rossi',
      azienda: 'La Tua Azienda',
      sito_azienda: 'www.tuaazienda.it',

      // Volumi
      limite_giornaliero_default: 20, // mail a freddo al giorno per casella (se in CASELLE manca limite_cold_giorno)
      lead_per_esecuzione: 8, // lead analizzati al massimo a ogni giro (il workflow gira ogni ora 9-17)
      ora_ultimo_giro: 17,
      pausa_min_secondi: 40, // pausa casuale tra un invio e l'altro
      pausa_max_secondi: 120,

      // Analisi del sito con Claude
      modello: 'claude-opus-5-5',
      effort: 'medium',
      confidenza_minima: 0.7, // sotto questa soglia la prova non regge e il lead va in DA GUARDARE
      caratteri_massimi_pagina: 15000,
    },
  },
];

// ---- Funzioni comuni NOVA (incluse automaticamente in ogni nodo Code) ----
const CFG = $('IMPOSTAZIONI').first().json;

// Righe lette da un nodo Google Sheets (scarta le righe vuote)
function righe(nodo, colonnaChiave) {
  return $(nodo)
    .all()
    .map((i) => i.json)
    .filter((r) => r && String(r[colonnaChiave] ?? '').trim() !== '');
}

function si(v) {
  return ['si', 'sì', 'yes', 'y', 'true', '1', 'x', 'ok'].includes(String(v ?? '').trim().toLowerCase());
}

function pulisci(v) {
  return String(v ?? '').trim();
}

function normEmail(v) {
  return pulisci(v).toLowerCase();
}

function dominio(email) {
  return normEmail(email).split('@')[1] || '';
}

// Data di oggi nel fuso del workflow (YYYY-MM-DD)
function oggi() {
  return $now.toFormat('yyyy-MM-dd');
}

// Interpreta le date scritte nel foglio: 2026-10-05, 05/10/2026, numero seriale di Sheets
function leggiData(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromISO('1899-12-30', { zone: $now.zoneName }).plus({ days: Math.floor(v) }).startOf('day');
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: $now.zoneName });
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if (m) return DateTime.fromObject({ year: +m[3], month: +m[2], day: +m[1] }, { zone: $now.zoneName });
  return null;
}

// Giorni interi trascorsi da una data del foglio (null se la data manca)
function giorniDa(v) {
  const d = leggiData(v);
  if (!d) return null;
  return Math.floor($now.startOf('day').diff(d.startOf('day'), 'days').days);
}

function scegli(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// Sostituisce {segnaposto} nel testo
function riempi(testo, valori) {
  return String(testo ?? '').replace(/\{([a-z_]+)\}/gi, (tutto, k) =>
    valori[k] !== undefined && valori[k] !== null ? String(valori[k]) : tutto,
  );
}

// Testi dalla scheda TESTI: { chiave: [varianti...] }
function caricaTesti(nodo) {
  const testi = {};
  for (const r of righe(nodo, 'chiave')) {
    const k = pulisci(r.chiave).toLowerCase();
    const t = String(r.testo ?? '').replace(/\\n/g, '\n').trim();
    if (!t) continue;
    (testi[k] = testi[k] || []).push(t);
  }
  return testi;
}

function testo(testi, chiave, obbligatorio = true) {
  const v = testi[chiave];
  if (!v || !v.length) {
    if (obbligatorio) {
      throw new Error(`Nella scheda TESTI manca la chiave "${chiave}". Aggiungila prima di attivare il workflow.`);
    }
    return '';
  }
  return scegli(v);
}

// Caselle collegate nel workflow 00 (scheda CASELLE)
function caselle(nodo) {
  return righe(nodo, 'email')
    .filter((c) => si(c.attiva))
    .map((c) => ({
      ...c,
      email_foglio: pulisci(c.email),
      slot: parseInt(c.slot, 10),
      email: normEmail(c.email),
      ruolo: pulisci(c.ruolo).toUpperCase() || 'INVIO',
      pronta: pulisci(c.stato_warmup).toUpperCase() === 'COMPLETATO',
    }))
    .filter((c) => c.slot >= 1 && c.slot <= 10);
}

// Elenco opt-out / bounce (scheda BLACKLIST)
function caricaBlacklist(nodo) {
  const email = new Set();
  const domini = new Set();
  for (const r of $(nodo).all().map((i) => i.json)) {
    if (pulisci(r.email)) email.add(normEmail(r.email));
    if (pulisci(r.dominio)) domini.add(pulisci(r.dominio).toLowerCase());
  }
  return { email, domini, contiene: (e) => email.has(normEmail(e)) || domini.has(dominio(e)) };
}

// ---- Logica del nodo ----
// Sceglie quali lead lavorare in questo giro e da quale casella scrivere (a turno).
const tutte = caselle('Leggi CASELLE').filter((c) => c.ruolo === 'INVIO');
let pronte = tutte.filter((c) => c.pronta);
if (!pronte.length && CFG.modalita_test) pronte = tutte; // in test si può provare anche durante il warm-up
if (!pronte.length) return []; // warm-up non ancora finito: non parte niente

// Regole e testi devono esserci, altrimenti il workflow si ferma
const regoleAttive = righe('Leggi REGOLE', 'id').filter((r) => si(r.attiva));
if (!regoleAttive.length) throw new Error('Nella scheda REGOLE non c\'è nessuna regola con attiva = SI.');
const testi = caricaTesti('Leggi TESTI');
for (const k of ['oggetto', 'saluto', 'proposta', 'chiusura', 'firma']) testo(testi, k);

const coda = righe('Leggi CODA', 'lead_id');
const blacklist = caricaBlacklist('Leggi BLACKLIST');

// Invii già fatti oggi per casella
const inviateOggi = {};
for (const r of coda) {
  if (leggiData(r.data_invio)?.toFormat('yyyy-MM-dd') === oggi()) {
    const k = normEmail(r.casella);
    inviateOggi[k] = (inviateOggi[k] || 0) + 1;
  }
}

// Capacità di questo giro: quota rimasta divisa per i giri rimasti oggi
const giriRestanti = Math.max(1, CFG.ora_ultimo_giro - $now.hour + 1);
const capacita = pronte.map((c) => {
  const limite = parseInt(c.limite_cold_giorno, 10) || CFG.limite_giornaliero_default;
  const restanti = Math.max(0, limite - (inviateOggi[c.email] || 0));
  return { casella: c, posti: Math.ceil(restanti / giriRestanti) };
});

// Email già contattate (in qualunque riga non NUOVO)
const contattate = new Set(
  coda.filter((r) => pulisci(r.stato).toUpperCase() !== 'NUOVO').map((r) => normEmail(r.email)),
);
const candidati = coda
  .filter((r) => pulisci(r.stato).toUpperCase() === 'NUOVO' && pulisci(r.email) && pulisci(r.sito))
  .filter((r) => !blacklist.contiene(r.email) && !contattate.has(normEmail(r.email)));

const out = [];
let giro = 0;
for (const lead of candidati) {
  if (out.length >= CFG.lead_per_esecuzione) break;
  if (contattate.has(normEmail(lead.email))) continue; // stessa email già scelta in questo giro
  // prossima casella con posti liberi, a turno
  let scelta = null;
  for (let t = 0; t < capacita.length; t++) {
    const c = capacita[(giro + t) % capacita.length];
    if (c.posti > 0) {
      scelta = c;
      giro = (giro + t + 1) % capacita.length;
      break;
    }
  }
  if (!scelta) break;
  scelta.posti--;
  contattate.add(normEmail(lead.email));
  out.push({
    json: {
      lead_id: pulisci(lead.lead_id),
      nome: pulisci(lead.nome),
      categoria: pulisci(lead.categoria),
      citta: pulisci(lead.citta),
      sito: pulisci(lead.sito),
      email: normEmail(lead.email),
      slot: scelta.casella.slot,
      casella: scelta.casella.email,
      nome_mittente: pulisci(scelta.casella.nome_mittente) || CFG.nome_mittente,
    },
  });
}
return out;

